export default function BlogDetail() {
  const { id } = useParams();
  const [comment, setComment] = useState("");
  const [bold, setBold] = useState(false);
  const [italic, setItalic] = useState(false);
  const date = new Date().toDateString();
  const [blogPost, setBlogPost] = useState({
    title: "article introuvable ou supprimé",
    image: bootverif,
    contenu:
      "contenu introuvable ou supprimé par l'administrateur du site. verifiez votre connection internet et votre url dans le cas contraire , veuillez nous contacter.",
    reference: "../BootVerif",
    author: "BootVerif ",
    date: date,
  });

  const blogId = Number(id);
  const finding = blog.find((post) => post.id === blogId);
  useEffect(() => {
    if (finding) {
      setBlogPost(finding);
    }
  }, [finding]);
  console.log(blogPost);
  // Redirect to 404 if service is not found

  const handleBold = () => {
    setBold(!bold);
  };

  const handleItalic = () => {
    setItalic(!italic);
  };

  const handleLink = () => {
    setComment(comment + " [link](url) ");
  };

  const handleCommentChange = (e) => {
    setComment(e.target.value);
  };

  const handleSubmit = () => {
    // Logique pour soumettre le commentaire
    console.log("Commentaire soumis:", comment);
  };

  return (
    <div className="all">
      <Navbar />
      <div className="bg-gray-100 py-16">
        <div className="container mx-auto px-4 flex flex-col lg:flex-row">
          <div className="lg:w-3/4 p-8">
            {/* Image du blog */}
            <img
              src={blogPost.image}
              alt="Blog"
              className="w-full h-64 object-cover rounded-lg mb-6"
            />
            {/* Titre du blog */}
            <h1 className="text-4xl font-semibold mb-4"> {blogPost.title} </h1>
            {/* Contenu du blog */}
            <p className="text-lg  text-justify text-gray-600 mb-6">
              {blogPost.contenu}
            </p>

            {/* Informations supplémentaires sous forme compacte */}
            <div className="text-gray-500 mt-4 mb-6 space-y-1">
              <p>
                <span className="text-gray-500 font-semibold">Date :</span>{" "}
                {blogPost.date} <span className="text-green-500 ">✔</span>
              </p>
              <p>
                <span className=" text-gray-500font-semibold">Auteur :</span>{" "}
                {blogPost.author} <span className="text-green-500 ">✔</span>
              </p>
              <p>
                <span className=" font-semibold">Référence :</span>{" "}
                <a
                  href={blogPost.reference}
                  className="text-red-500 hover:underline"
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  Lien vers l'article <span className="text-green-500 ">✔</span>
                </a>
              </p>
              <span
                className=" text-red-500 font-bold"
                onClick={Navigate("/404", "me")}
              >
                {" "}
                <br />
                <hr />
                <br />
                Discuter avec nous ? <br />
                <button
                  onClick={handleSubmit}
                  className="bg-red-950 text-white px-4 py-2 rounded"
                >
                  Contactez nous
                </button>
              </span>{" "}
            </div>
          </div>

          <div className="lg:w-1/4 p-8 bg-white shadow-lg rounded-lg">
            <div className="mb-6">
              <h3 className="text-2xl font-semibold mb-4">Blogs Récents</h3>
              <ul>
                {recentBlogs.map((blog) => (
                  <li key={blog.id} className="mb-6 flex items-center">
                    <img
                      src={blog.image}
                      alt={blog.title}
                      className="w-16 h-16 object-cover rounded mr-4"
                    />
                    <Link
                      to={`/blog/${blog.id}`}
                      className="text-red-500 hover:underline"
                    >
                      {blog.title}
                    </Link>
                  </li>
                ))}
              </ul>
            </div>
            <div>
              <h3 className="text-2xl font-semibold mb-4">Blogs Connexes</h3>
              <ul>
                {relatedBlogs.map((blog) => (
                  <li key={blog.id} className="mb-6 flex items-center">
                    <img
                      src={blog.image}
                      alt={blog.title}
                      className="w-16 h-16 object-cover rounded mr-4"
                    />
                    <Link
                      to={`/blog/${blog.id}`}
                      className="text-red-500 hover:underline"
                    >
                      {blog.title}
                    </Link>
                  </li>
                ))}
              </ul>
            </div>
          </div>
        </div>

        {/* Section Commentaires */}
        <div className="bg-white mx-16 p-6 rounded-lg shadow-lg mt-8">
          <h3 className="text-2xl font-semibold mb-4">
            Laissez un commentaire
          </h3>
          <div className="mb-4 flex items-center">
            <button
              onClick={handleBold}
              className={`mr-2 px-3 py-1 rounded ${
                bold ? "bg-gray-300" : "bg-gray-200"
              }`}
            >
              <strong>B</strong>
            </button>
            <button
              onClick={handleItalic}
              className={`mr-2 px-3 py-1 rounded ${
                italic ? "bg-gray-300" : "bg-gray-200"
              }`}
            >
              <em>I</em>
            </button>
            <button
              onClick={handleLink}
              className="px-3 py-1 rounded bg-gray-200"
            >
              🔗
            </button>
          </div>
          <textarea
            value={comment}
            onChange={handleCommentChange}
            className="w-full p-4 border border-gray-300 rounded mb-4"
            rows={4}
            placeholder="Votre commentaire..."
            style={{
              fontWeight: bold ? "bold" : "normal",
              fontStyle: italic ? "italic" : "normal",
            }}
          />
          <button
            onClick={handleSubmit}
            className="bg-red-950 text-white px-4 py-2 rounded"
          >
            Envoyer
          </button>

          <div>
            <h3 className="text-2xl font-semibold m-4">Commentaires</h3>
            <ul>
              {comments.map((comment) => (
                <li key={comment.id} className="mb-6">
                  <p className="text-gray-600">{comment.content}</p>
                  <small className="text-gray-500 ">
                    {comment.author}
                  </small>{" "}
                  <u>
                    {" "}
                    <small className="text-gray-500 ">le {comment.date} </small>
                  </u>{" "}
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
}
